document.addEventListener("alpine:init", () => {
  Alpine.data("registrarEnrollment", () => ({
    enrollMode: false,
    errors: {},
    loading: false,
    records: [],
    search: "",

    // get searchRecord() {
    //   const search = this.search.toLowerCase().trim();

    //   if (!search) {
    //     return this.records;
    //   }

    //   return this.records.filter((record) => {
    //     return (
    //       record.student_id?.toLowerCase().includes(search) ||
    //       record.firstname?.toLowerCase().includes(search) ||
    //       record.lastname?.toLowerCase().includes(search) ||
    //       record.middlename?.toLowerCase().includes(search)
    //     );
    //   });
    // },

    form: {
      student_id: "",
      firstname: "",
      lastname: "",
      middlename: "",
      suffix: "",
      sex: "",
      birthdate: "",
      email: "",
      contact_no: "",
      contact_person: "",
      address: "",
      course: "",
      section: "",
      student_type: "",
      year_level: "",
      academic_year: "",
      semester: "",
    },

    init() {
      this.getNewEnrollment();
    },

    course: {
      1: "DPIT",
      2: "DPTHT",
      3: "DPET",
      4: "DPFT",
      5: "DPWT",
    },
    student_type: {
      new: "badge text-bg-primary text-capitalize",
      transferee: "badge text-bg-warning text-capitalize",
      returning: "badge text-bg-success text-capitalize",
    },
    async enroll() {
      this.loading = true;
      this.errors = {};

      try {
        const formData = new FormData();

        formData.append("student_id", this.form.student_id);
        formData.append("firstname", this.form.firstname);
        formData.append("lastname", this.form.lastname);
        formData.append("middlename", this.form.middlename);
        formData.append("suffix", this.form.suffix);
        formData.append("sex", this.form.sex);
        formData.append("birthdate", this.form.birthdate);
        formData.append("email", this.form.email);
        formData.append("contact_no", this.form.contact_no);
        formData.append("contact_person", this.form.contact_person);
        formData.append("address", this.form.address);
        formData.append("course", this.form.course);
        formData.append("section", this.form.section);
        formData.append("student_type", this.form.student_type);
        formData.append("year_level", this.form.year_level);
        formData.append("academic_year", this.form.academic_year);
        formData.append("semester", this.form.semester);

        const res = await fetch("manage-enrollment", {
          method: "POST",
          body: formData,
          headers: {
            "X-Requested-With": "XMLHttpRequest",
          },
        });

        const data = await res.json();

        if (!res.ok) {
          throw new Error(data.message || "Enrollment failed.");
        }

        if (data.status === 200) {
          Swal.fire({
            icon: "success",
            title: "Enrollment Successful",
            text: data.message,
            confirmButtonText: "OK",
          });
          this.getNewEnrollment();
          this.resetForm();
        } else {
          this.errors = data.errors || {};

          Swal.fire({
            icon: "error",
            title: "Enrollment Failed",
            text: data.message || "Please check the form.",
          });
        }
      } catch (error) {
        console.error(error);

        Swal.fire({
          icon: "error",
          title: "Something went wrong",
          text: error.message || "Unable to process the enrollment.",
        });
      } finally {
        this.loading = false;
      }
    },

    resetForm() {
      this.form = {
        student_id: "",
        firstname: "",
        lastname: "",
        middlename: "",
        suffix: "",
        sex: "",
        birthdate: "",
        email: "",
        contact_no: "",
        contact_person: "",
        address: "",
        course_id: "",
        section: "",
        student_type: "",
        year_level: "",
        academic_year: "",
        semester: "",
      };

      this.errors = {};
      this.enrollMode = false;
    },

    async getNewEnrollment() {
      const res = await fetch(`/registrar/manage-enrollment/records`);

      const data = await res.json();

      if (data.records) {
        this.records = data.records;
        console.log(this.records);
      }
    },
  }));
});
